<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{api}from'../api';import PageHeader from'../components/PageHeader.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{RefreshCw}from'lucide-vue-next';const rows=ref<any[]>([]);const cols=[{key:'access_key',label:'Chave'},{key:'document_type',label:'Tipo'},{key:'status',label:'Situação'},{key:'progress',label:'Progresso'},{key:'attempts',label:'Tentativas'},{key:'created_at',label:'Iniciado'}];async function load(){rows.value=(await api.get('/retrieval-jobs')).data}let timer:any;onMounted(()=>{load();timer=setInterval(load,5000);window.addEventListener('tenant-changed',load)});onUnmounted(()=>{clearInterval(timer);window.removeEventListener('tenant-changed',load)})
</script><template><PageHeader title="Jobs e operações" subtitle="Acompanhe consultas, lotes, retentativas e ações humanas em tempo real"><button class="btn" @click="load"><RefreshCw :size="16"/>Atualizar</button></PageHeader><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-document_type="{value}">{{value.toUpperCase()}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-progress="{value}"><div class="progress"><i :style="{width:`${value}%`}"></i></div><small>{{value}}%</small></template><template #cell-attempts="{value}">{{value.length}}</template><template #cell-created_at="{value}">{{new Date(value).toLocaleString('pt-BR')}}</template></DataTable></section></template>
